# patch_v47 (replaces v45 and v46): Program Analyzer (any file or program, static only), long-document reader, and a
# Gemma "booster": bundled knowledge notes searched on every question, a multi-step reading pipeline,
# docx/epub/pdf/csv readers, capability + call-graph analysis, and a learning loop you approve.
# Needs v44 applied first. Bundles proganalyze.py, gemmaboost.py, rambo_knowledge.py, appagent.py. Backup: main.py.bak47.
# Run inside ~/BusinessDashboard:  python patch_v47.py
import os, sys, shutil, py_compile, base64, zlib, hashlib, re

F = "main.py"
if not os.path.exists(F):
    sys.exit("STOPPED: main.py not found (run this inside ~/BusinessDashboard)")
src = open(F, encoding="utf-8").read()
if "# ---------- v47: Program" in src:
    sys.exit("Already patched (v47). Nothing to do.")
if "def prog_route" in src:
    for old in (".bak46", ".bak45"):
        if os.path.exists(F + old):
            shutil.copy(F + old, F)
            src = open(F, encoding="utf-8").read()
            print("An earlier analyzer patch was applied; v47 replaces it. Restored main.py from main.py" + old + " first.")
            break
    else:
        sys.exit("STOPPED: an earlier analyzer patch is applied but its backup is missing, so v47 cannot replace it safely.")
if not os.path.exists(F + ".bak47"):
    shutil.copy(F, F + ".bak47")

MODS = {
    'proganalyze.py': ('421fed38441244574bbf72ad52dc02dc9ebcf4e59c75b9cfa99b1e1f8b330852', ''),
    'gemmaboost.py': ('488df2ce6943556aadf9a3ca14305c0bf4e650736111ef5d000d742082956c38', ''),
    'rambo_knowledge.py': ('7b807b42a66febf2767c3a83cdd1215729e3857653b499fb9ab9d3854fb91fa0', ''),
    'appagent.py': ('ae923acb0b1442f78fc60b416d1ce869f1109111d03d316c8c533b905d9f47a5', ''),
}
blobs = {}
for name, (sha, b64) in MODS.items():
    data = zlib.decompress(base64.b64decode(b64))
    if hashlib.sha256(data).hexdigest() != sha:
        sys.exit("STOPPED: bundled %s is damaged. Download patch_v47.py again." % name)
